"""送一個帶工具定義的請求到本機 Ollama，看它回不回工具呼叫。"""
import json
import os
import urllib.request

BASE = os.environ.get("LOCAL_BASE_URL", "http://localhost:11434/v1")
MODEL = os.environ.get("LOCAL_MODEL", "qwen3.6")
TOOLS = [
  {
    "type": "function",
    "function": {
      "name": "read_file",
      "description": "讀取工作目錄底下的一個檔案",
      "parameters": {
        "type": "object",
        "properties": {"path": {"type": "string"}},
        "required": ["path"],
      },
    },
  }
]


def ask(prompt: str) -> dict:
  body = json.dumps(
    {
      "model": MODEL,
      "messages": [{"role": "user", "content": prompt}],
      "tools": TOOLS,
      "stream": False,
    }
  ).encode("utf-8")
  request = urllib.request.Request(
    f"{BASE}/chat/completions",
    data=body,
    headers={
      "Content-Type": "application/json",
      # 相容端點要求用戶端填一個金鑰值，但 Ollama 會忽略它。
      "Authorization": "Bearer ollama",
    },
  )
  with urllib.request.urlopen(request, timeout=120) as response:
    return json.loads(response.read())


def main() -> int:
  answer = ask("請讀取 README.md，並回報它的第一行。")
  message = answer["choices"][0]["message"]
  calls = message.get("tool_calls") or []
  print(f"模型 {answer.get('model')}：工具呼叫 {len(calls)} 次")
  for call in calls:
    print(" ", call["function"]["name"], call["function"]["arguments"])
  if not calls:
    print("沒有工具呼叫；接上編碼代理多半只會得到一段說明文字。")
  return 0 if calls else 1


if __name__ == "__main__":
  raise SystemExit(main())
